#!/usr/bin/env python3
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
spv_dir = root / "shaders" / "spv"
out = root / "src" / "generated" / "shaders_spv.h"
entries = [
    ("kGeomVertSpv", "geom.vert.spv"),
    ("kGeomFragSpv", "geom.frag.spv"),
    ("kFullscreenVertSpv", "fullscreen.vert.spv"),
    ("kEdgeFragSpv", "edge.frag.spv"),
    ("kFinalFragSpv", "final.frag.spv"),
]
lines = [
    "// Generated by scripts/embed_shaders.py; do not edit by hand.",
    "#pragma once",
    "#include <cstddef>",
    "#include <cstdint>",
    "",
    "namespace ssor::shaders {",
    "",
]
for name, filename in entries:
    data = (spv_dir / filename).read_bytes()
    lines.append(f"inline constexpr std::uint32_t {name}[] = {{")
    for i in range(0, len(data), 4):
        word = int.from_bytes(data[i:i+4], "little")
        lines.append(f"    0x{word:08x}u,")
    lines.append("};")
    lines.append(f"inline constexpr std::size_t {name}Size = sizeof({name});")
    lines.append("")
lines.append("}  // namespace ssor::shaders")
lines.append("")
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("\n".join(lines), encoding="ascii")
print(f"embedded {len(entries)} shaders -> {out.relative_to(root)}")
